window.AUTH=window.AUTH||{};window.AUTH["23-971"]={"d":"23-971","id":"2024/23-971","n":"Waetzig v. Halliburton Energy Services, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Gary Waetzig","date":"2024-11-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/332068/20241118132019967_23-971%20Brief%20for%20Petitioner.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondent Halliburton Energy Services, Inc.","date":"2024-12-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/335492/20241218142610310_Waetzig%20v.%20Halliburton%20-%20Brief%20for%20Respondent.pdf","side":"res","n":107},{"k":"reply","label":"Reply of petitioner Gary Waetzig","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-971/336508/20250103114805695_23-971%20Reply.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r14_6kg7.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"0":"25"}},{"t":"case","label":"Axon Enter., Inc. v. Fed. Trade Comm’n","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"by":{"0":"47"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Communities for a Great Oregon","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"by":{"0":"21, 22"}},{"t":"case","label":"Badgerow v. Walters","cite":"596 U.S. 1","y":2022,"id":"2021/20-1143","sc":1,"by":{"0":"6","1":"2, 6, 10, 16, 17, 20, 40","2":"4"},"q":[{"src":"brief","b":1,"text":"limited jurisdiction, defined (within constitutional bounds) by federal statute.","cite":"596 U.S. 1, 7"},{"src":"argument","who":"Mr. Levy","text":"And the argument will fail on remand because it misreads Badgerow and Kokkonen, which are the two cases my friends rely upon. And when it comes to the question presented, Respondent offers no cogent response to the dictionary definitions, the -- California decisions, or the advisory notes."},{"src":"argument","who":"Mr. Levy","text":"Well, it -- it's related in the sense that it -- it -- as the Court looked at the question in Badgerow, the question of -- of a -- a motion to -- to vacate an award, and there, of course, the merits were not before the Court, it was a standalone motion to vacate."},{"src":"argument","who":"Justice Kagan","text":"Well, assume that -- if you assume that -- I think that Badgerow would prevent you from just relying on the federal statute to vacate the arbitration award."}]},{"t":"case","label":"Bell v. New Jersey","cite":"461 U.S. 773","y":1983,"id":"1982/81-2125","sc":1,"by":{"0":"16"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"‘intended to depart from established principles’ such as the scope of a court’s inherent power.","cite":"501 U.S. 32, 47"}]},{"t":"case","label":"Coca-Cola Co. v. City of Atlanta","cite":"110 S.E. 730","y":1922,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./110/730/","by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"[s]ome act, or acts, done in furtherance of the enforcement of an existing right, real or imaginary.","cite":"110 S.E. 730, 733"}]},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"0":"16","1":"24","2":"8"}},{"t":"case","label":"Commonwealth, to Use of Beckingham v. Magee","cite":"73 A. 346","y":1909,"court":"Pa.","url":"https://www.courtlistener.com/c/A./73/346/","by":{"0":"36","1":"46"}},{"t":"case","label":"Confederated Tribes & Bands of Yakama Nation v. Okanogan County","cite":"16 Wash App. 2d 1030","y":2021,"url":"https://www.courtlistener.com/c/Wash%20App.%202d/16/1030/","by":{"0":"23"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"by":{"0":"31, 42"},"q":[{"src":"brief","b":0,"text":"dismissals or nonsuits as a matter of right [were often allowed] until the entry of the verdict.","cite":"496 U.S. 384, 397"},{"src":"brief","b":0,"text":"without the permission of the adverse party or the court only during the brief period before the defendant had made a significant commitment of time and money.","cite":"496 U.S. at 397"}]},{"t":"case","label":"Davenport v. Hardman","cite":"192 S.E. 11","y":1937,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./192/11/","by":{"0":"32"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"[a] title will not, of course, ‘override the plain words’ of a statute","cite":"599 U.S. 110, 121"}]},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"25"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"by":{"0":"21","1":"35, 41"},"q":[{"src":"brief","b":0,"text":"teaches that a word is ‘given more precise content by the neighboring words with which it is associated.’","cite":"603 U.S. 480, 487"},{"src":"brief","b":0,"text":"is typically controlled and defined by reference to the specific classes . . . that precede it.","cite":"603 U.S. at 487"},{"src":"brief","b":1,"text":"teaches that a word is ‘given more precise content by the neighboring words with which it is associated.’","cite":"603 U.S. 480, 487"},{"src":"brief","b":1,"text":"renders meaningless the specific text that accompanies it.","cite":"603 U.S. at 487"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"`given more precise content by the neighboring words with which it is associated.'","cite":"603 U. S. 480, 487"}]},{"t":"case","label":"Fish Mkt. Nominee Corp. v. Pelofsky","cite":"72 F.3d 4","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/72/4/","by":{"0":"21"}},{"t":"case","label":"Fla. Dep’t of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"by":{"0":"25"}},{"t":"case","label":"Friel v. Alewel","cite":"298 S.W. 762","y":1927,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./298/762/","by":{"0":"24"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"593 U.S. 522","y":2021,"id":"2020/19-123","sc":1,"by":{"0":"25"}},{"t":"case","label":"Gillespie v. U.S. Steel Corp.","cite":"379 U.S. 148","y":1964,"id":"1964/10","sc":1,"by":{"0":"16","1":"29"},"q":[{"src":"brief","b":0,"text":"the requirement of finality is to be given a ‘practical rather than a technical construction.’","cite":"379 U.S. 148, 152"},{"src":"brief","b":1,"text":"the requirement of finality is to be given a ‘practical rather than a technical construction’","cite":"379 U.S. 148, 152"}]},{"t":"case","label":"Graham v. Superior Mines","cite":"49 P.2d 443","y":1935,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/49/443/","by":{"0":"33"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"by":{"0":"10, 13, 30, 38, 40, 41, 45","1":"11, 22, 24, 29","2":"8, 16–17"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"`a reliable source of insight into the meaning of a rule.'","cite":"584 U. S. 59, 75"}]},{"t":"case","label":"Harjo v. Black","cite":"153 P. 1137","y":1915,"court":"Okla.","url":"https://www.courtlistener.com/c/P./153/1137/","by":{"0":"36","1":"46"}},{"t":"case","label":"Harrington v. Purdue Pharma L. P.","cite":"144 S. Ct. 2071","y":2024,"id":"2023/23-124","sc":1,"by":{"0":"24"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"by":{"0":"23"}},{"t":"case","label":"Hazel-Atlas Glass Co. v. Hartford-Empire Co.","cite":"322 U.S. 238","y":1944,"id":"scdb/1943-040","sc":1,"by":{"0":"34","1":"43"},"q":[{"src":"brief","b":0,"text":"From the beginning there has existed along side the term rule a rule of equity to the effect that under certain circumstances, one of which is after-discovered fraud, relief will be granted against judgments regardless of the term of their entry.","cite":"322 U.S. 238, 244"}]},{"t":"case","label":"Hoodless v. Winter","cite":"16 S.W. 427","y":1891,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W./16/427/","by":{"0":"37"}},{"t":"case","label":"Horne v. Flores","cite":"557 U.S. 433","y":2009,"id":"2008/08-289","sc":1,"by":{"0":"3, 15, 16"}},{"t":"case","label":"Jackson v. Waldron","cite":"5 F. 245","y":1880,"court":"C.C.W.D. Tenn.","url":"https://www.courtlistener.com/c/F./5/245/","by":{"0":"36","1":"44, 45"}},{"t":"case","label":"Jacobellis v. Ohio","cite":"378 U.S. 184","y":1964,"id":"1963/11","sc":1,"by":{"0":"7"},"q":[{"src":"brief","b":0,"text":"Perhaps ‘final proceeding’ is a catchall, covering anything that does not result in an order or judgment but still involves a final, burdensome judicial determination. And perhaps we will ‘know it when [we] see it.’ But we know that Mr. Waetzig’s voluntary dismissal without prejudice is not it.","cite":"378 U.S. 184, 197"}]},{"t":"case","label":"John Simmons Co. v. Grier Brothers","cite":"258 U.S. 82","y":1922,"id":"scdb/1921-053","sc":1,"by":{"0":"43"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"a rehearing may be sought at any time before [the] fnal decree, provided due diligence be employed and a revision be otherwise consonant with equity.","cite":"258 U. S. 82, 90–91"},{"src":"argument","who":"Mr. Levy","text":"And Professor Moore, in -- in the article that is referenced in the advisory committee notes, says that's wrong because, as this Court had said in 1922 in the John Simmons Company case, courts retain plenary inherent authority to revisit interlocutory matters and that's how it should be."}]},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"by":{"0":"39"}},{"t":"case","label":"Keith Mfg. Co. v. Butterfield","cite":"955 F.3d 936","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/955/936/","by":{"0":"28"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"0":"22","1":"2, 10, 15, 16, 18, 19, 20, 37, 40, 50","2":"2, 4–5"},"q":[{"src":"brief","b":1,"text":"more than just a continuation or renewal of the dismissed suit * * * requires its own basis for jurisdiction.","cite":"511 U.S. 375, 378"},{"src":"argument","who":"Mr. Levy","text":"And the argument will fail on remand because it misreads Badgerow and Kokkonen, which are the two cases my friends rely upon. And when it comes to the question presented, Respondent offers no cogent response to the dictionary definitions, the -- California decisions, or the advisory notes."},{"src":"argument","who":"Mr. Levy","text":"And I -- I didn't read the majority -- the opinion of the Court to say otherwise. Kokkonen itself, upon which Badgerow was based, made very clear --"},{"src":"argument","who":"Chief Justice Roberts","text":"We know from Kokkonen and Rule 82 that Rule 60 cannot extend the jurisdiction of the district court to new forms of relief, such as a motion to vacate an arbitral award."}]},{"t":"case","label":"Krupski v. Costa Crociere S. p. A.","cite":"560 U.S. 538","y":2010,"id":"2009/09-337","sc":1,"by":{"0":"30"}},{"t":"case","label":"Lacey v. Citizens’ Lumber & Supply Co.","cite":"248 N.W. 378","y":1933,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./248/378/","by":{"0":"34"}},{"t":"case","label":"Link v. Anselm","cite":"1910 WL 3096","y":1910,"court":"Pa.","by":{"0":"37"}},{"t":"case","label":"Link v. Wabash R, Co.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"by":{"0":"38, 42, 46","1":"49"},"q":[{"src":"brief","b":1,"text":"avoid the consequences of the acts or omissions of [their] freely selected agent.","cite":"370 U.S. 626, 633-634"}]},{"t":"case","label":"Lusas v. St. Patrick’s Roman Cath. Church Corp. of Waterbury","cite":"193 A. 204","y":1937,"court":"Conn.","url":"https://www.courtlistener.com/c/A./193/204/","by":{"0":"10, 32, 33, 35, 40, 48","1":"46, 47","2":"18–19"},"q":[{"src":"brief","b":0,"text":"where the parties have a right without consent of court to withdraw or voluntarily dismiss the case.","cite":"193 A. at 206"},{"src":"brief","b":1,"text":"conflict in the decisions in other jurisdictions.","cite":"193 A. 204, 206"},{"src":"brief","b":2,"text":"[o]f the cases cited by the defendant","cite":"193 A. at 206"},{"src":"argument","who":"Mr. Levy","text":"That's reflected in -- by the -- in the decision of the Supreme Court of Connecticut, in the Lusas decision, which cites not only California for this point but also New York, which is one of the statutes that is cited by the rules committee."}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"gives effect to every clause and word of [Rule 60(b)],","cite":"568 U.S. 371, 385"}]},{"t":"case","label":"Millar v. Whittington","cite":"105 S.E. 907","y":1921,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E./105/907/","by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"[t]he term ‘proceeding,’ as applied to suits, means any step or measure taken in the prosecution or defense of an action.","cite":"105 S.E. 907, 908"}]},{"t":"case","label":"Miller v. Fortune Ins. Co.","cite":"484 So. 2d 1221","y":1986,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/484/1221/","by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"Surely, a voluntary notice of dismissal is something, it doesn’t exist in limbo. We conclude that it is indeed a ‘proceeding.’","cite":"484 So. 2d 1221, 1224"}]},{"t":"case","label":"National Power & Paper Co. v. Rossman","cite":"142 N.W. 818","y":1913,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./142/818/","by":{"0":"38"}},{"t":"case","label":"Nelson v. Adams USA, Inc.","cite":"529 U.S. 460","y":2000,"id":"1999/99-502","sc":1,"by":{"0":"12"}},{"t":"case","label":"Occidental Life Ins. Co. v. Niendorf","cite":"44 P.2d 1099","y":1935,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/44/1099/","by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"during the term at which rendered.","cite":"44 P.2d 1099, 1102"}]},{"t":"case","label":"Palace Hardware Co. v. Smith","cite":"66 P. 474","y":1901,"court":"Cal.","url":"https://www.courtlistener.com/c/P./66/474/","by":{"0":"10, 39, 40","1":"47","2":"18"},"q":[{"src":"brief","b":0,"text":"upon such terms as may be just, [to] relieve a party or his legal representatives from a judgment, order, or other proceeding taken against him through his mistake, inadvertence, surprise or excusable neglect.","cite":"66 P. at 476"},{"src":"brief","b":0,"text":"judgment of dismissal on the order of the plaintiff,","cite":"66 P. at 476"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"consented to [a] dismissal to his injury, under a mistake of fact, excusable under the terms of the statute, . . . is not barred of relief.","cite":"66 P. 474, 476"}]},{"t":"case","label":"Pedrina v. Chun","cite":"987 F.2d 608","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/987/608/","by":{"0":"3"}},{"t":"case","label":"Pestana v. State","cite":"762 S.E.2d 178","y":2014,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/762/178/","by":{"0":"34"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"0":"20"}},{"t":"case","label":"Preveden v. Hahn","cite":"36 F. Supp. 952","y":1941,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./36/952/","by":{"0":"35"}},{"t":"case","label":"Randall v. Merrill","cite":"820 F.2d 1317","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/820/1317/","by":{"0":"29"}},{"t":"case","label":"Reaume v. Carpenter","cite":"89 N.W. 953","y":1902,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./89/953/","by":{"0":"37"}},{"t":"case","label":"Redman v. United States","cite":"2023 WL 8519201","y":2023,"court":"3d Cir. Dec. 8","by":{"0":"22"}},{"t":"case","label":"Ross v. Eagle Coal Co.","cite":"36 S.W.2d 48","y":1931,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/36/48/","by":{"0":"37"}},{"t":"case","label":"Ruch v. State","cite":"146 N.E. 67","y":1924,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./146/67/","by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"include[s] all methods of invoking the action of courts and embrace[s] any controversy which may or may not rise to the dignity of a suit or action.","cite":"146 N.E. 67, 71"},{"src":"brief","b":0,"text":"method[] of invoking the action of [a] court[],","cite":"146 N.E. at 71"}]},{"t":"case","label":"Rufo v. Inmates of Suffolk County Jail","cite":"502 U.S. 367","y":1992,"id":"1991/90-954","sc":1,"by":{"0":"3","1":"37"}},{"t":"case","label":"Ryan v. Phoenix Ins. Co. of Hartford, Conn.","cite":"215 N.W. 749","y":1927,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./215/749/","by":{"0":"37, 48"}},{"t":"case","label":"S. Grocery Stores v. Cain","cite":"173 S.E. 256","y":1934,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./173/256/","by":{"0":"37"}},{"t":"case","label":"Salazar v. Steelman","cite":"71 P.2d 79","y":1937,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/71/79/","by":{"0":"40","1":"47","2":"18"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"All the -- all the Petitioner has to point to in that is the Salazar case, which is a single decision of a single intermediate appellate court in California."}]},{"t":"case","label":"Schmier v. McDonald’s LLC","cite":"69 F.3d 1240","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/69/1240/","by":{"0":"26, 28"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"by":{"0":"2, 31"}},{"t":"case","label":"Shreveport Long Leaf Lumber Co. v. Jones","cite":"177 So. 593","y":1937,"court":"La.","url":"https://www.courtlistener.com/c/So./177/593/","by":{"0":"32"}},{"t":"case","label":"Siegfried v. New York, L.E. & W.R. Co.","cite":"34 N.E. 331","y":1893,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./34/331/","by":{"0":"32"}},{"t":"case","label":"Spellacy v. Superior Ct. in & for Los Angeles Cnty.","cite":"72 P.2d 262","y":1937,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/72/262/","by":{"0":"40"}},{"t":"case","label":"Stonesifer v. Kilburn","cite":"29 P. 332","y":1892,"court":"Cal.","url":"https://www.courtlistener.com/c/P./29/332/","by":{"0":"39","2":"17–18"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"And the -- the Stonesifer case he cites says -- says a proceeding covers -- you know, covers any step in the action seeking court action. A dismissal without prejudice, a non-suit, is the opposite of that."}]},{"t":"case","label":"Storey v. Storey","cite":"221 F. 262","y":1915,"court":"W.D. Wis.","url":"https://www.courtlistener.com/c/F./221/262/","by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"The rule applicable to final judgments and decrees is well known and of constant application. When a final judgment is entered, it may be vacated during the judgment term. However conclusive in its character, it is still under the control of the trial court, and may be amended, suspended, or vacated at any time up to the close of that term, but not afterwards, unless in some way carried over by proceedings during the judgment term.","cite":"221 F. 262, 263"}]},{"t":"case","label":"Thompson v. Bay Circuit Judge","cite":"101 N.W. 61","y":1904,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./101/61/","by":{"0":"38, 48"},"q":[{"src":"argument","who":"Mr. Levy","text":"Chief Justice, and may it please the Court: As ever -- every Federal Circuit to have considered the question held until the decision below, Rule 41 voluntary dismissals without prejudice may be reopened under Rule 60(b) because they are final proceedings or final judgments."},{"src":"argument","who":"Justice Thomas","text":"Didn't the Tenth Circuit also treat this as jurisdictional?"},{"src":"argument","who":"Mr. Levy","text":"The -- the Tenth Circuit treated the decision -- the issue of whether Rule 60(b) could be -- whether the case could be reopened as going to the jurisdiction of the court to vacate the award, and, therefore, there are two, effectively, threshold issues that could be resolved."}]},{"t":"case","label":"Torres v. Oakland Scavenger Co.","cite":"487 U.S. 312","y":1988,"id":"1987/86-1845","sc":1,"by":{"0":"22"}},{"t":"case","label":"Turkiye Halk Bankasi A. S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"by":{"0":"20"}},{"t":"case","label":"Uhe v. Chicago, M. & St. P. Ry. Co.","cite":"54 N.W. 601","y":1893,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W./54/601/","by":{"0":"25"}},{"t":"case","label":"United States v. Benz","cite":"282 U.S. 304","y":1931,"id":"scdb/1930-114","sc":1,"by":{"0":"34"}},{"t":"case","label":"United States v. Mayer","cite":"235 U.S. 55","y":1914,"id":"scdb/1914-027","sc":1,"by":{"0":"35","1":"14, 44"},"q":[{"src":"brief","b":0,"text":"courts of common law . . . at a subsequent term ha[d] power to correct inaccuracies in mere matters of form, or clerical errors, and, in civil cases, to rectify such mistakes of fact as were reviewable on writs of error coram nobis, or coram vobis, for which the proceeding by motion is the modern substitute.","cite":"235 U.S. 55, 67"},{"src":"brief","b":1,"text":"this authority can neither be conferred upon nor withheld from the courts of the United States by the statutes of a state.","cite":"235 U.S. 55, 69"}]},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"[t]he rule of ejusdem generis is no more than an aid to construction and comes into play only when there is some uncertainty as to the meaning of a particular clause in a statute.","cite":"452 U.S. 576, 581"}]},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"by":{"0":"13","2":"8"},"q":[{"src":"brief","b":0,"text":"Advisory Committee Notes are ‘a reliable source of insight into the meaning of a rule’","cite":"535 U.S. 55, 64 n.6"}]},{"t":"case","label":"United States v. Whiting","cite":"165 F.3d 631","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/165/631/","by":{"0":"28"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"0":"21"}},{"t":"case","label":"Walker Bros. Inv., Inc. v. City of Mobile","cite":"252 So. 3d 57","y":2017,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%203d/252/57/","by":{"0":"23"}},{"t":"case","label":"Weinberger v. Romero–Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"by":{"0":"38"}},{"t":"case","label":"White v. Nat’l Football League","cite":"756 F.3d 585","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/585/","by":{"0":"15, 29","2":"24"},"q":[{"src":"brief","b":2,"text":"[t]hat the Rules call one of these means a ‘judgment’ strongly suggests that the drafters would have intended to treat the other as a judgment as well.","cite":"756 F.3d 585, 595–96"}]},{"t":"case","label":"Willard v. Wood","cite":"1 App. D.C. 44","y":1893,"court":"App. D.C.","url":"https://www.courtlistener.com/c/App.%20D.C./1/44/","by":{"0":"31","1":"44"}},{"t":"case","label":"Williams v. Frey","cite":"551 F.2d 932","y":1977,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/551/932/","by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"dismissal of [a] suit was . . . a proceeding","cite":"551 F.2d 932, 935"}]},{"t":"case","label":"Yesh Music v. Lakewood Church","cite":"727 F.3d 356","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/356/","by":{"0":"14, 23"},"q":[{"src":"argument","who":"Mr. Levy","text":"So ours wins under both standards. And we took -- we -- we -- we endorsed, I think, something closer to Yesh from the Fifth Circuit --"}]},{"t":"case","label":"Zamora v. Clayborn Contracting Group, Inc.","cite":"47 P.3d 1056","y":2002,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/47/1056/","by":{"0":"41"}},{"t":"case","label":"Zimmerman v. Western Builders’ & Salvage Co.","cite":"297 P. 449","y":1931,"court":"Ariz.","url":"https://www.courtlistener.com/c/P./297/449/","by":{"0":"37"}},{"t":"usc","label":"28 U.S.C. § 2071","url":"https://www.law.cornell.edu/uscode/text/28/2071","stext":{"head":"§2071. Rule-making power generally","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may from time to time prescribe rules for the conduct of their business. Such rules shall be consistent with Acts of Congress and rules of practice and procedure prescribed under section 2072 of this title."],[0,"(b) Any rule prescribed by a court, other than the Supreme Court, under subsection (a) shall be prescribed only after giving appropriate public notice and an opportunity for comment. Such rule shall take effect upon the date specified by the prescribing court and shall have such effect on pending proceedings as the prescribing court may order."],[0,"(c)(1) A rule of a district court prescribed under subsection (a) shall remain in effect unless modified or abrogated by the judicial council of the relevant circuit."],[0,"(2) Any other rule prescribed by a court other than the Supreme Court under subsection (a) shall remain in effect unless modified or abrogated by the Judicial Conference."],[0,"(d) Copies of rules prescribed under subsection (a) by a district court shall be furnished to the judicial council, and copies of all rules prescribed by a court other than the Supreme Court under subsection (a) shall be furnished to the Director of the Administrative Office of the United States Courts and made available to the public."],[0,"(e) If the prescribing court determines that there is an immediate need for a rule, such court may proceed under this section without public notice and opportunity for comment, but such court shall promptly thereafter afford such notice and opportunity for comment."],[0,"(f) No rule may be prescribed by a district court other than under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2071?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 31","1":"45"}},{"t":"rule","label":"Fed. R. Civ. P. 1","url":"https://www.law.cornell.edu/rules/frcp/rule_1","by":{"0":"47","1":"45"},"q":[{"src":"brief","b":1,"text":"the just, speedy, and inexpensive determination","cite":"Fed. R. Civ. P. 1"}]},{"t":"rule","label":"Fed. R. Civ. P. 37","url":"https://www.law.cornell.edu/rules/frcp/rule_37","subs":["(b)"],"by":{"0":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(a)","(d)","(a)(1)(A)","(a)(1)(B)"],"by":{"0":"2–9, 11–19, 22–35, 41, 46–49, 21","1":"5, 32, 37, 5, 37","2":"1, 5, 15–16, 23–25, 5, 15, 21, 23–25"},"q":[{"src":"brief","b":0,"text":"[u]nless the notice or stipulation states otherwise, the dismissal is without prejudice","cite":"Fed. R. Civ. P. 41(a)(1)(B)"},{"src":"brief","b":1,"text":"the plaintiff previously dismissed any federal- or statecourt action based on or including the same claim.","cite":"Fed. R. Civ. P. 41(a)(1)(B)"},{"src":"brief","b":1,"text":"operates as an adjudication on the merits,","cite":"Fed. R. Civ. P. 41(a)(1)(B)"}]},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)","(c)","(a)","(c)(1)","(c)(2)","(e)"],"by":{"0":"1, 3, 5–31, 33, 35, 39–49, 20","1":"42, 24, 25, 1, 3, 8, 11, 12, 13, 15, 21, 23, 24, 28, 31, 32, 34, 36, 28, 25, 44","2":"1–9, 15–23, 25, 1–9, 15–17, 19, 21–22"},"q":[{"src":"brief","b":0,"text":"relieve a party or its legal representative from a final judgment, order, or proceeding.","cite":"Fed. R. Civ. P. 60(b)"},{"src":"brief","b":0,"text":"[a] motion under Rule 60(b) must be made . . . no more than a year after the entry of the judgment or order or the date of the proceeding.","cite":"Fed. R. Civ. P. 60(c)"},{"src":"brief","b":1,"text":"relie[f ] * * * from a final judgment, order, or proceeding","cite":"Fed. R. Civ. P. 60(b)"},{"src":"brief","b":1,"text":"plaintiff can only obtain relief under Rule 60(b) if his voluntary dismissal without prejudice under Rule 41(a) qualifies as ‘a final judgment, order, or proceeding.’","cite":"Fed. R. Civ. P. 60(b)"}]},{"t":"case","label":"Adair Bus Sales, Inc. v. Blue Bird Corp.","cite":"25 F.3d 953","y":1994,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/25/953/","by":{"1":"4"}},{"t":"case","label":"American States Insurance Co. v. Capital Associates of Jackson County, Inc.","cite":"392 F.3d 939","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/939/","by":{"1":"26","2":"12"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"by":{"1":"36"}},{"t":"case","label":"Bankers Trust Co. v. Mallis","cite":"435 U.S. 381","y":1978,"id":"1977/76-1359","sc":1,"by":{"1":"13, 32","2":"23–24"},"q":[{"src":"brief","b":1,"text":"‘final decision’ as that term is used","cite":"435 U.S. 381, 384 n.4"},{"src":"brief","b":1,"text":"appear[s] to be equivalent to a ‘final decision’ as that term is used in 28 U.S.C. § 1291.","cite":"435 U.S. 381, 384 n.4"},{"src":"brief","b":2,"text":"[a] ‘judgment’ for purposes of the Federal Rules of Civil Procedure would appear to be equivalent to a ‘final decision’ as that term is used in 28 U.S.C. § 1291.","cite":"435 U.S. 381, 384 n.4"}]},{"t":"case","label":"Barnes v. Whiteman","cite":"9 Dowl. 181","y":1840,"court":"Q.B.","url":"https://www.courtlistener.com/c/Dowl./9/181/","by":{"1":"46"}},{"t":"case","label":"Bender v. Williamsport Area School District","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"by":{"1":"16, 17"},"q":[{"src":"brief","b":1,"text":"‘not only of its own jurisdiction, but also that of the lower courts in a cause under review.’","cite":"475 U.S. 534, 541"},{"src":"argument","who":"Justice Jackson","text":"McGILL: This Court should care about it because it goes to the lower court's jurisdiction under this Court's decision in Bender versus Williamsport --"},{"src":"argument","who":"Justice Jackson","text":"McGILL: The -- the same, of course, was true in Bender versus Williamsport Area School District. This Court has an independent obligation, even if I were prepared to concede jurisdiction, it has its own obligation to assure itself of its jurisdiction and those of the courts below."}]},{"t":"case","label":"Bostwick v. Brinkerhoff","cite":"106 U.S. 3","y":1882,"id":"scdb/1882-004","sc":1,"by":{"1":"23","2":"10"},"q":[{"src":"brief","b":1,"text":"terminate[s] the litigation between the parties on the merits of the case, so that if there should be an affirmance * * * the court below would have nothing to do but to execute the judgment or decree it had already rendered.","cite":"106 U.S. 3, 3-4"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"`terminate[s] the litigation between the parties on the merits of the case.'","cite":"106 U. S., at 3"}]},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"create equitable exceptions to jurisdictional requirements,","cite":"551 U.S. 205, 214"}]},{"t":"case","label":"Browder v. Director, Department of Corrections of Illinois","cite":"434 U.S. 257","y":1978,"id":"1977/76-5325","sc":1,"by":{"1":"30"}},{"t":"case","label":"Budinich v. Becton Dickinson & Co.","cite":"486 U.S. 196","y":1988,"id":"1987/87-283","sc":1,"by":{"1":"24, 28"},"q":[{"src":"brief","b":1,"text":"[c]ourts and litigants are best served by [a] bright-line rule, which accords with traditional understanding.","cite":"486 U.S. at 202"}]},{"t":"case","label":"California v. Texas","cite":"593 U.S. 659","y":2021,"id":"2020/19-840","sc":1,"by":{"1":"17"},"q":[{"src":"argument","who":"Mr. Levy","text":"The phrase \"judgment, order, or proceeding\" in Rule 60(b) was taken in 1937 from Section 473 of California's Code of Civil Procedure, and at the time, California's Supreme Court had interpreted Section 473 to cover all steps in litigation and it's -- it had specifically applied Section 473 to voluntary dismissals."},{"src":"argument","who":"Mr. Levy","text":"And in terms of -- of the question presented, it -- the text is clear and the California courts are clear that proceedings and judgments are to be -- proceedings are to be interpreted broadly."},{"src":"argument","who":"Mr. Levy","text":"They made very clear initially that it covered whatever California covered, which is everything. And then the word \"final\" was added later to make clear that the courts' authority over interlocutory matters was not constrained."}]},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"by":{"1":"23, 29","2":"10"},"q":[{"src":"brief","b":1,"text":"dispos[es] of all issues involved in the litigation.","cite":"324 U.S. 229, 236"},{"src":"brief","b":2,"text":"dispos[es] of all issues involved in the litigation.","cite":"324 U.S. 229, 236"}]},{"t":"case","label":"Central Transportation Co. v. Pullman’s Palace Car Co.","cite":"139 U.S. 24","y":1891,"id":"scdb/1890-151","sc":1,"by":{"1":"12, 26","2":"14"},"q":[{"src":"brief","b":2,"text":"plaintiff[] who appears by the record to have voluntarily become nonsuit.","cite":"139 U.S. 24, 39"}]},{"t":"case","label":"Chiarodit v. Chiarodit","cite":"21 P.2d 562","y":1933,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/21/562/","by":{"1":"24"}},{"t":"case","label":"Commissioner v. Bedford’s Estate","cite":"325 U.S. 283","y":1945,"id":"scdb/1944-160","sc":1,"by":{"1":"33","2":"25"},"q":[{"src":"brief","b":1,"text":"judgment is the act of the court,","cite":"325 U.S. 283, 286"}]},{"t":"case","label":"Cone v. West Virginia Pulp & Paper Co.","cite":"330 U.S. 212","y":1947,"id":"scdb/1946-056","sc":1,"by":{"1":"25, 27, 50","2":"12"}},{"t":"case","label":"Costello v. United States","cite":"365 U.S. 265","y":1961,"id":"1960/59","sc":1,"by":{"1":"26"}},{"t":"case","label":"Farrar v. Hobby","cite":"506 U.S. 103","y":1992,"id":"1992/91-990","sc":1,"by":{"1":"37"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"by":{"1":"23, 41"},"q":[{"src":"brief","b":1,"text":"two words together may assume a more particular meaning than those words in isolation,","cite":"562 U.S. 397, 406"}]},{"t":"case","label":"Frank v. Gaos","cite":"586 U.S. 485","y":2019,"id":"2018/17-961","sc":1,"by":{"1":"32"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"by":{"1":"19, 48","2":"5"},"q":[{"src":"brief","b":1,"text":"although labeled a Rule 60(b) motion, is in substance a successive habeas petition.","cite":"545 U.S. 524, 531"},{"src":"brief","b":1,"text":"the text of Rule 60(b) itself.","cite":"545 U.S. at 529"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"to make an exception to fnality.","cite":"545 U. S. 524, 529"}]},{"t":"case","label":"Guam v. United States","cite":"593 U.S. 310","y":2021,"id":"2020/20-382","sc":1,"by":{"1":"43"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"by":{"1":"50"}},{"t":"case","label":"Hall Street Associates, LLC v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"by":{"1":"17"}},{"t":"case","label":"Hensley v. Henry","cite":"400 N.E.2d 1352","y":1980,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/400/1352/","by":{"1":"42"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"1":"30"}},{"t":"case","label":"Jackson v. Merritt","cite":"21 D.C. 276","y":1892,"url":"https://www.courtlistener.com/c/D.C./21/276/","by":{"1":"46"}},{"t":"case","label":"Janssen v. Harris","cite":"321 F.3d 998","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/321/998/","by":{"1":"31"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"by":{"1":"14, 22, 45, 47","2":"17, 19"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"by":{"1":"19"}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"by":{"1":"33"}},{"t":"case","label":"Lundahl v. Halabi","cite":"600 F. App’x 596","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/600/596/","by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"an order granting dismissal is superfluous, a nullity, and without procedural effect,","cite":"600 F. App’x 596, 603"}]},{"t":"case","label":"Marshall v. Kansas City Southern Railway Co.","cite":"378 F.3d 495","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/495/","by":{"1":"26","2":"12"},"q":[{"src":"brief","b":1,"text":"‘is entitled to bring a later suit on the same cause of action.’","cite":"378 F.3d 495, 500"},{"src":"brief","b":2,"text":"use [of] voluntary dismissal[s] without prejudice as an end-run around the final judgment rule to convert an otherwise non-final—and thus non-appealable—ruling into a final decision appealable under § 1291.","cite":"378 F.3d 495, 500"},{"src":"argument","who":"Justice Gorsuch","text":"It goes back to Justice -- Chief Justice Marshall riding circuit in North Carolina in 1803 in Marsh versus Murray. We cite that case in our brief."}]},{"t":"case","label":"Melkonyan v. Sullivan","cite":"501 U.S. 89","y":1991,"id":"1990/90-5538","sc":1,"by":{"1":"32, 38"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"582 U.S. 23","y":2017,"id":"2016/15-457","sc":1,"by":{"1":"12, 26, 27, 29, 30","2":"12–15"},"q":[{"src":"brief","b":1,"text":"that would erode the finality principle and disserve its objectives.","cite":"582 U.S. at 37"},{"src":"argument","who":"Justice Gorsuch","text":"And -- and then Microsoft, how do you deal with that, where this Court said that a dismissal with prejudice wasn't a final decision for purposes of 1291?"}]},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"by":{"1":"23"}},{"t":"case","label":"Mohawk Industries, Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"1":"48"}},{"t":"case","label":"Murray v. Marsh","cite":"17 F. Cas. 1059","y":1803,"court":"C.C.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Cas./17/1059/","by":{"1":"44"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"It goes back to Justice -- Chief Justice Marshall riding circuit in North Carolina in 1803 in Marsh versus Murray. We cite that case in our brief."}]},{"t":"case","label":"Owen Equipment & Erection Co. v. Kroger","cite":"437 U.S. 365","y":1978,"id":"1977/77-677","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"the Federal Rules of Civil Procedure do not create or withdraw federal jurisdiction.","cite":"437 U.S. 365, 370"}]},{"t":"case","label":"Pitchess v. Davis","cite":"421 U.S. 482","y":1975,"id":"1974/74-1128","sc":1,"by":{"1":"19"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"by":{"1":"43"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"is generally read the same way each time it appears.","cite":"510 U.S. 135, 143"}]},{"t":"case","label":"Reno v. Bossier Parish School Board","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"by":{"1":"23, 29"},"q":[{"src":"brief","b":1,"text":"depending on which object it is modifying.","cite":"528 U.S. 320, 329"}]},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"1":"48"}},{"t":"case","label":"Rudolph v. Sensener","cite":"39 App. D.C. 385","y":1912,"url":"https://www.courtlistener.com/c/App.%20D.C./39/385/","by":{"1":"26","2":"14"},"q":[{"src":"brief","b":1,"text":"because the action may be brought anew.","cite":"39 App. D.C. 385, 387"}]},{"t":"case","label":"Sandstrom v. ChemLawn Corp.","cite":"904 F.2d 83","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/904/83/","by":{"1":"38"}},{"t":"case","label":"Simpson v. Brock","cite":"40 S.E. 266","y":1901,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./40/266/","by":{"1":"46"}},{"t":"case","label":"SmartSky Networks, LLC v. DAG Wireless, Ltd.","cite":"93 F.4th 175","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/175/","by":{"1":"39"}},{"t":"case","label":"Smith v. Spizzirri","cite":"601 U.S. 472","y":2024,"id":"2023/22-1218","sc":1,"by":{"1":"4, 40"}},{"t":"case","label":"Smurda v. Superior Court","cite":"266 P. 843","y":1928,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P./266/843/","by":{"1":"47","2":"18"},"q":[{"src":"brief","b":2,"text":"recognized conflict among intermediate California courts.","cite":"266 P. 843"}]},{"t":"case","label":"Snyder v. Harris","cite":"394 U.S. 332","y":1969,"id":"1968/109","sc":1,"by":{"1":"19"}},{"t":"case","label":"Southern Railway Co. v. Miller","cite":"217 U.S. 209","y":1910,"id":"scdb/1909-128","sc":1,"by":{"1":"37"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"in light of any ‘common attribute[s]’ shared by the specific items.","cite":"596 U.S. 450, 458"}]},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"by":{"1":"25","2":"9"},"q":[{"src":"argument","who":"Justice Thomas","text":"So the -- the rule -- the -- and also, this Court's decision in Stone versus INS, which we cite in our red brief, elaborates on how Rule 60 and the Rules of Appellate Procedure work together to define the -- the time to file a notice of appeal."}]},{"t":"case","label":"Summers v. Earth Island Institute","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"by":{"1":"17"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"by":{"1":"34"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"by":{"1":"39"}},{"t":"case","label":"Treasurer of State of Michigan v. Barry","cite":"168 F.3d 8","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/8/","by":{"1":"26","2":"12"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"a handful of writs, the precise contours of which were ‘shrouded in ancient lore and mystery.’","cite":"524 U.S. 38, 43"},{"src":"argument","who":"Justice Gorsuch","text":"If you look at the Beggerly case, the district court has subject matter jurisdiction to entertain an independent action attack -- attacking the judgment for --"}]},{"t":"case","label":"United States v. L-3 Communications EOTech, Inc.","cite":"921 F.3d 11","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/921/11/","by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"hornbook law that ‘a voluntary dismissal without prejudice under Rule 41(a) leaves the situation as if the action never had been filed.’","cite":"921 F.3d 11, 19"}]},{"t":"case","label":"United States v. Merz","cite":"376 U.S. 192","y":1964,"id":"1963/65","sc":1,"by":{"1":"37"}},{"t":"case","label":"Weisguth v. Supreme Tribe of Ben Hur","cite":"112 N.E. 350","y":1916,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E./112/350/","by":{"1":"14, 46"}},{"t":"case","label":"Wetmore v. Karrick","cite":"205 U.S. 141","y":1907,"id":"scdb/1906-144","sc":1,"by":{"1":"44"}},{"t":"case","label":"Wilson v. Republic Iron & Steel Co.","cite":"257 U.S. 92","y":1921,"id":"scdb/1921-013","sc":1,"by":{"1":"24","2":"9, 10, 21"},"q":[{"src":"brief","b":1,"text":"effectually terminates the particular case, prevents the plaintiff from further prosecuting the same and relieves the defendant from putting in a defense.","cite":"257 U.S. 92, 96"},{"src":"brief","b":2,"text":"prevent[ing] the plaintiff from further prosecuting the [case] and reliev[ing] the defendant from putting in a defense.","cite":"257 U.S. at 96"}]},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","by":{"1":"4"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","stext":{"head":"§10. Same; vacation; grounds; rehearing","paras":[[0,"(a) In any of the following cases the United States court in and for the district wherein the award was made may make an order vacating the award upon the application of any party to the arbitration—"],[1,"(1) where the award was procured by corruption, fraud, or undue means;"],[1,"(2) where there was evident partiality or corruption in the arbitrators, or either of them;"],[1,"(3) where the arbitrators were guilty of misconduct in refusing to postpone the hearing, upon sufficient cause shown, or in refusing to hear evidence pertinent and material to the controversy; or of any other misbehavior by which the rights of any party have been prejudiced; or"],[1,"(4) where the arbitrators exceeded their powers, or so imperfectly executed them that a mutual, final, and definite award upon the subject matter submitted was not made."],[0,"(b) If an award is vacated and the time within which the agreement required the award to be made has not expired, the court may, in its discretion, direct a rehearing by the arbitrators."],[0,"(c) The United States district court for the district wherein an award was made that was issued pursuant to section 580 of title 5 may make an order vacating the award upon the application of a person, other than a party to the arbitration, who is adversely affected or aggrieved by the award, if the use of arbitration or the award is clearly inconsistent with the factors set forth in section 572 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/10?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2, 6"},"q":[{"src":"argument","who":"Mr. Levy","text":"And my client then challenged the award by going back to court and saying we would like to reopen the case and have the arbitration vacated under Section 10 of the FAA."},{"src":"argument","who":"Chief Justice Roberts","text":"We know from Badgerow that a Section 10 motion to vacate under the Federal Arbitration Act requires its own basis for federal jurisdiction."}]},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 26, 32","2":"6–7, 12–13, 21–23"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"35"}},{"t":"rule","label":"Fed. R. App. P. 4","url":"https://www.law.cornell.edu/rules/frap/rule_4","subs":["(a)(4)(A)(vi)"],"by":{"1":"25"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"1":"33"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(a)"],"by":{"1":"13, 32, 33","2":"24"},"q":[{"src":"brief","b":1,"text":"includ[e] a decree and any order from which an appeal lies.","cite":"Fed. R. Civ. P. 54(a)"}]},{"t":"rule","label":"Fed. R. Civ. P. 55","url":"https://www.law.cornell.edu/rules/frcp/rule_55","subs":["(c)"],"by":{"1":"42"}},{"t":"rule","label":"Fed. R. Civ. P. 58","url":"https://www.law.cornell.edu/rules/frcp/rule_58","subs":["(a)","(b)"],"by":{"1":"33, 35, 33","2":"23–24"}},{"t":"rule","label":"Fed. R. Civ. P. 69","url":"https://www.law.cornell.edu/rules/frcp/rule_69","by":{"1":"36, 43"},"q":[{"src":"brief","b":1,"text":"proceedings supplementary to and in aid of judgment or execution.","cite":"Fed. R. Civ. P. 69(a)(1)"}]},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","by":{"1":"36"}},{"t":"rule","label":"Fed. R. Civ. P. 79","url":"https://www.law.cornell.edu/rules/frcp/rule_79","subs":["(b)"],"by":{"1":"41"}},{"t":"rule","label":"Fed. R. Civ. P. 82","url":"https://www.law.cornell.edu/rules/frcp/rule_82","by":{"1":"11, 19"},"q":[{"src":"brief","b":1,"text":"extend * * * the jurisdiction of the district courts.","cite":"Fed. R. Civ. P. 82"}]},{"t":"case","label":"Allied Air Freight, Inc. v. Pan Am. World Airways, Inc.","cite":"393 F.3d 441","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/393/441/","by":{"2":"11–12"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"by":{"2":"23"}},{"t":"case","label":"City of Sherrill, N.Y. v. Oneida Indian Nation of New York","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"by":{"2":"22"}},{"t":"case","label":"HollyFrontier Cheyenne Ref., LLC v. Renewable Fuels Ass’n","cite":"594 U.S. 382","y":2021,"id":"2020/20-472","sc":1,"by":{"2":"7–8"}},{"t":"case","label":"Kelly v. Great Atl. & Pac. Tea Co.","cite":"86 F.2d 296","y":1936,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/86/296/","by":{"2":"13, 22"},"q":[{"src":"brief","b":2,"text":"although a voluntary nonsuit is a final termination of the action, it has been entered at the request of plaintiff, and he may not, after causing the order to be entered, complain of it on appeal.","cite":"86 F.2d 296, 296– 97"}]},{"t":"case","label":"Lauderdale-El v. Indiana Parole Bd.","cite":"35 F.4th 572","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/35/572/","by":{"2":"11"}},{"t":"case","label":"LeCompte, v. Mr. Chip, Inc.","cite":"528 F.2d 601","y":1976,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/528/601/","by":{"2":"14"},"q":[{"src":"brief","b":2,"text":"[w]here the trial court allows the plaintiff to dismiss his action without prejudice, the judgment, of course, qualifies as a final judgment for purposes of appeal. Ordinarily though, plaintiff cannot appeal therefrom, since it does not qualify as an involuntary adverse judgment so far as the plaintiff is concerned.","cite":"528 F.2d 601, 603"}]},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"by":{"2":"1–3"},"q":[{"src":"brief","b":2,"text":"[t]he Court of Appeals did not rule on th[is] alternative ground[], which [is] beyond the scope of the question presented.","cite":"586 U.S. 188, 198"},{"src":"brief","b":2,"text":"[i]f the Court of Appeals concludes that these arguments have been preserved, it can address them in the first instance on remand.","cite":"586 U.S. at 198"}]},{"t":"case","label":"Pac. Bell Tel. Co. v. linkLine Commc’ns, Inc.","cite":"555 U.S. 438","y":2009,"id":"2008/07-512","sc":1,"by":{"2":"2"}},{"t":"case","label":"PennEast Pipeline Company, LLC v. New Jersey","cite":"594 U.S. 482","y":2021,"id":"2020/19-1039","sc":1,"by":{"2":"3"}},{"t":"case","label":"Rinieri v. News Syndicate Co.","cite":"385 F.3d 818","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/385/818/","by":{"2":"11"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co., Inc.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"by":{"2":"17"}},{"t":"case","label":"United States v. Evans","cite":"9 U.S. 280","y":1809,"id":"scdb/1809-015","sc":1,"by":{"2":"14"},"q":[{"src":"brief","b":2,"text":"that in such a case, where there has been a nonsuit, and a motion to reinstate overruled, the court could not interfere.","cite":"9 U.S. 280, 281"}]},{"t":"case","label":"United States v. Stitt","cite":"586 U.S. 27","y":2018,"id":"2018/17-765","sc":1,"by":{"2":"2"}},{"t":"case","label":"Wecker v. Nat’l Enameling & Stamping Co.","cite":"204 U.S. 176","y":1907,"id":"scdb/1906-207","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"[w]hether th[e] judgment would be a bar to another action.","cite":"204 U.S. 176, 182"},{"src":"brief","b":2,"text":"[I]t [wa]s final, so far as the case is concerned, and terminated the action.","cite":"204 U.S. at 182"}]},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 225","url":"https://www.law.cornell.edu/uscode/text/28/225","subs":["(a)(1946)"],"by":{"2":"6–7"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)"],"by":{"2":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(f)"],"by":{"2":"13"}},{"t":"rule","label":"Fed. R. Civ. P. 62","url":"https://www.law.cornell.edu/rules/frcp/rule_62","by":{"2":"20–21"}},{"t":"rule","label":"Fed. R. Civ. P. 68","url":"https://www.law.cornell.edu/rules/frcp/rule_68","by":{"2":"24"}}]};